<style>
  html,body{margin:0;padding:0;height:100%;background:transparent;overflow:hidden;font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;color:var(--viz-text,#e6edf3);}
  .scene{perspective:900px;position:relative;width:100%;height:100%;display:flex;align-items:center;justify-content:center;min-height:360px;}
  .wrap{position:relative;transform-style:preserve-3d;animation:spin 8s linear infinite;width:180px;height:180px;}
  .cube{position:absolute;inset:0;transform-style:preserve-3d;}
  .face{position:absolute;width:180px;height:180px;display:flex;align-items:center;justify-content:center;font-size:44px;font-weight:800;letter-spacing:2px;border:1px solid var(--viz-border,rgba(255,255,255,.18));backdrop-filter:blur(6px);background:linear-gradient(135deg,var(--viz-card,rgba(30,40,60,.7)),rgba(0,0,0,.35));box-shadow:inset 0 0 40px rgba(255,255,255,.06);}
  .f{font-size:18px;color:var(--viz-muted,#9aa4b2);margin-top:6px;}
  .face.front{transform:translateZ(90px);}
  .face.back{transform:rotateY(180deg) translateZ(90px);}
  .face.right{transform:rotateY(90deg) translateZ(90px);}
  .face.left{transform:rotateY(-90deg) translateZ(90px);}
  .face.top{transform:rotateX(90deg) translateZ(90px);}
  .face.bottom{transform:rotateX(-90deg) translateZ(90px);}
  .glow{position:absolute;inset:-40px;border-radius:50%;background:radial-gradient(circle,var(--viz-accent,#5b9cff) 0%,transparent 60%);opacity:.25;filter:blur(20px);pointer-events:none;}
  @keyframes spin{0%{transform:rotateX(-18deg) rotateY(0deg);}100%{transform:rotateX(-18deg) rotateY(360deg);}}
  .label{position:absolute;bottom:16px;left:50%;transform:translateX(-50%);font-size:13px;color:var(--viz-muted,#9aa4b2);letter-spacing:3px;text-transform:uppercase;}
  .btns{position:absolute;top:12px;right:12px;display:flex;gap:6px;}
  button{background:var(--viz-card,rgba(255,255,255,.08));color:var(--viz-text,#e6edf3);border:1px solid var(--viz-border,rgba(255,255,255,.15));border-radius:8px;padding:6px 10px;font-size:12px;cursor:pointer;}
  button:hover{background:var(--viz-accent,#5b9cff);color:#fff;}
