<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8"/>
<meta name="viewport" content="width=device-width,initial-scale=1"/>
<title>Particle Physics Playground</title>
<style>
  :root{
    --bg:#0a0e18; --panel:#121826; --card:#1a2233; --border:#2a3550;
    --text:#e6ecff; --muted:#9aa6c7; --accent:#7c8cff; --accent2:#4dd0e1; --danger:#ff6b7a; --ok:#5ee3a3;
  }
  *{box-sizing:border-box}
  html,body{margin:0;padding:0;height:100%;background:var(--bg);color:var(--text);font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;overflow:hidden}
  .app{display:flex;flex-direction:column;height:100vh;gap:8px;padding:10px}
  header{display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:6px 4px}
  header h1{font-size:16px;margin:0;font-weight:600;letter-spacing:.3px}
  .stats{display:flex;gap:14px;font-size:12px;color:var(--muted);margin-left:auto}
  .stats span b{color:var(--text);font-variant-numeric:tabular-nums}
  .btnrow{display:flex;gap:6px;flex-wrap:wrap}
  button.b{background:var(--card);color:var(--text);border:1px solid var(--border);border-radius:8px;padding:6px 10px;font-size:12px;cursor:pointer;transition:.15s}
  button.b:hover{background:#222c44;border-color:var(--accent)}
  button.b.active{background:var(--accent);color:#0a0e18;border-color:var(--accent);font-weight:600}
  button.b.danger{border-color:var(--danger);color:var(--danger)}
  button.b.ok{border-color:var(--ok);color:var(--ok)}
  main{flex:1;min-height:0;position:relative;border:1px solid var(--border);border-radius:12px;overflow:hidden;background:#05080f}
  canvas{display:block;width:100%;height:100%;cursor:crosshair}
  .hud{position:absolute;top:8px;left:8px;font-size:11px;color:var(--muted);pointer-events:none;line-height:1.5}
  .hud .big{font-size:13px;color:var(--text);font-weight:600}
  footer{background:var(--panel);border:1px solid var(--border);border-radius:12px;padding:10px 12px;display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px 12px;max-height:42vh;overflow:auto}
  .ctrl{display:flex;flex-direction:column;gap:3px}
  .ctrl label{font-size:11px;color:var(--muted);display:flex;justify-content:space-between}
  .ctrl label b{color:var(--text);font-weight:500}
  input[type=range]{width:100%;accent-color:var(--accent)}
  .group{border-top:1px dashed var(--border);padding-top:6px;margin-top:2px}
  .group:first-child{border-top:none;padding-top:0;margin-top:0}
  .gtitle{font-size:10px;text-transform:uppercase;letter-spacing:.8px;color:var(--accent);margin-bottom:4px;font-weight:700}
  .toggles{display:flex;flex-wrap:wrap;gap:6px}
  .tog{display:flex;align-items:center;gap:5px;font-size:11px;color:var(--muted);cursor:pointer;padding:4px 8px;border:1px solid var(--border);border-radius:6px;background:var(--card)}
  .tog input{accent-color:var(--accent)}
  select.sel{background:var(--card);color:var(--text);border:1px solid var(--border);border-radius:6px;padding:5px 8px;font-size:12px;width:100%}
  .presetRow{display:flex;gap:4px;flex-wrap:wrap}
</style>
</head>
<body>
<div class="app">
